<script>
// FAQ Accordion
document.querySelectorAll('.faq-question').forEach(btn => {
  btn.addEventListener('click', () => {
    const item = btn.parentElement;
    const answer = item.querySelector('.faq-answer');
    const isOpen = item.classList.contains('open');

    document.querySelectorAll('.faq-item.open').forEach(openItem => {
      openItem.classList.remove('open');
      openItem.querySelector('.faq-answer').style.maxHeight = '0';
      openItem.querySelector('.faq-question').setAttribute('aria-expanded', 'false');
    });

    if (!isOpen) {
      item.classList.add('open');
      answer.style.maxHeight = answer.scrollHeight + 'px';
      btn.setAttribute('aria-expanded', 'true');
    }
  });
});

// Course Category Tabs
document.querySelectorAll('.course-tab').forEach(tab => {
  tab.addEventListener('click', () => {
    document.querySelectorAll('.course-tab').forEach(t => {
      t.classList.remove('active');
      t.setAttribute('aria-selected', 'false');
    });
    tab.classList.add('active');
    tab.setAttribute('aria-selected', 'true');

    const category = tab.dataset.tab;
    const cards = document.querySelectorAll('.course-card');

    cards.forEach(card => {
      const cats = card.dataset.categories.split(',');
      if (category === 'featured' || cats.includes(category)) {
        card.style.display = '';
        card.style.opacity = '0';
        card.style.transform = 'translateY(12px)';
        requestAnimationFrame(() => {
          requestAnimationFrame(() => {
            card.style.transition = 'opacity 0.3s ease, transform 0.3s ease';
            card.style.opacity = '1';
            card.style.transform = 'translateY(0)';
          });
        });
      } else {
        card.style.display = 'none';
      }
    });
  });
});

// Teacher Carousel
const carousel = document.getElementById('teacherCarousel');
const prevBtn = document.getElementById('teacherPrev');
const nextBtn = document.getElementById('teacherNext');
let carouselPos = 0;

function getCardWidth() {
  const card = carousel.querySelector('.teacher-card');
  return card ? card.offsetWidth + 24 : 284;
}

function getMaxScroll() {
  return Math.max(0, carousel.scrollWidth - carousel.parentElement.offsetWidth);
}

nextBtn.addEventListener('click', () => {
  carouselPos = Math.min(carouselPos + getCardWidth() * 2, getMaxScroll());
  carousel.style.transform = `translateX(-${carouselPos}px)`;
});

prevBtn.addEventListener('click', () => {
  carouselPos = Math.max(carouselPos - getCardWidth() * 2, 0);
  carousel.style.transform = `translateX(-${carouselPos}px)`;
});

// Smooth scroll for anchor links
document.querySelectorAll('a[href^="#"]').forEach(anchor => {
  anchor.addEventListener('click', function(e) {
    const target = document.querySelector(this.getAttribute('href'));
    if (target) {
      e.preventDefault();
      target.scrollIntoView({ behavior: 'smooth', block: 'start' });
    }
  });
});

// Intersection Observer for scroll animations
const observerOptions = { threshold: 0.1, rootMargin: '0px 0px -40px 0px' };
const observer = new IntersectionObserver((entries) => {
  entries.forEach(entry => {
    if (entry.isIntersecting) {
      entry.target.style.opacity = '1';
      entry.target.style.transform = 'translateY(0)';
      observer.unobserve(entry.target);
    }
  });
}, observerOptions);

document.querySelectorAll('.feature-card, .feed-card, .testimonial-card, .stat-item, .teacher-card').forEach(el => {
  el.style.opacity = '0';
  el.style.transform = 'translateY(24px)';
  el.style.transition = 'opacity 0.5s ease, transform 0.5s ease';
  observer.observe(el);
});
</script>

